✅️ multilinearCombine_recursive_form
  u : ∀ (r : Fin (n + 1) → ?m.154),
  have U₀ := (splitHalfRowWiseInterleavedWords u).1;
  have U₁ := (splitHalfRowWiseInterleavedWords u).2;
  have r_init := Fin.init r;
  multilinearCombine u r = multilinearCombine (affineLineEvaluation U₀ U₁ (r (Fin.last n))) r_init
